// React App Entry Point
// File: index.js
import React from "react";
import ReactDOM from "react-dom";
import App from "./App"; // Import the App component

ReactDOM.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>,
  document.getElementById("root") // Ensure "root" matches the `id` in your public/index.html
);
